"""15 фембой-тем. Правила символов: short/head*/tab_right/bar/footer/tagline/ambient/stop/names/tags — только ASCII
(их рисуют латинские шрифты и моно-шрифт Plymouth); sub/ask/refind/grub* — можно ♡ ･ω～ и японский (M PLUS Rounded)."""

def T(**kw):
    kw.setdefault("tags", {"ok": "[ uwu ]", "amb": "[ nya ]", "warn": "[ >_< ]"})
    kw.setdefault("enter", "boop!")
    kw.setdefault("ask", "パスワードください >w<")
    return kw

